// ─── IKI KATMANLI LIMIT ─────────────────────────────────────────────────
// 1) IP basina GUNLUK limit: tek kullanicinin sistemi spam'lemesini engeller.
// 2) GLOBAL AYLIK limit: Apify TikTok Trending calistirmasi basina ~$0.10
//    (20 sonuc, TR proxy filtresi dahil) -- TUM kullanicilar arasinda
//    paylasilan gercek butceyi korur. IP limiti bunu KORUMAZ -- 50 farkli
//    kullanici gunde 1'er istek atsa bile toplam kota hizla biter. Apify'in
//    aylik $5 ucretsiz kredisi ~50 calistirmaya denk geldigi icin, pay
//    birakmak icin 50 degil 45'te kesiyoruz.
const PER_IP_DAILY_LIMIT = 50;
// NOT: 'Build Search Query' 2 yerine 4 hashtag kullanmaya basladi (fyp,
// kesfet, turkiye, trendturkiye) -- Apify muhtemelen her hashtag icin ayri
// ucretlendiriyor, yani calistirma basina maliyet ~2 katina cikabilir. Ilk
// gercek test sonrasi Apify Storage/Usage sayfasindan gercek maliyeti
// kontrol edip bu sayiyi ona gore ayarla -- simdilik ihtiyatli baslangic.
const GLOBAL_MONTHLY_SEARCH_LIMIT = 25;

// Kota artik kullanici bazli (19 Eyl 2026). Uygulamadan gelen istekler n8n'e tek bir
// sunucu IP'siyle ulastigi icin butun kullanicilar ayni kovayi paylasiyordu. IP zaten
// guvenilir bir ayrac degil: mobil veride degisir, ortak wifi'de birlesir. Backend
// gercek kimligi govdede 'kkbKimlik' olarak yolluyor. WordPress'ten gelen giris
// yapmamis isteklerde bu alan olmaz, eskisi gibi IP'ye duseriz.
const kimlikGovde = $input.first().json.body || $input.first().json;
const ip = kimlikGovde.kkbKimlik || $input.first().json.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || $input.first().json.headers?.['x-real-ip'] || 'unknown';
const today = new Date().toISOString().slice(0, 10);
const monthKey = today.slice(0, 7); // 'YYYY-MM'
const ipKey = 'rl_trend_' + ip + '_' + today;
const globalKey = 'rl_trend_global_' + monthKey;

const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};
// 7 gunden eski sayaclari sil (15 Eyl 2026). Anahtarlar gun gun birikiyordu
// ('rl_<arac>_<ip>_<tarih>') ve hicbiri silinmedigi icin static data akisla
// birlikte kalici olarak buyuyor, zamanla akisi yavaslatiyordu.
const silSiniri = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
for (const k of Object.keys(staticData.rateLimits)) {
  const kTarih = k.slice(-10);
  if (/^\d{4}-\d{2}-\d{2}$/.test(kTarih) && kTarih < silSiniri) delete staticData.rateLimits[k];
}

const ipCount = staticData.rateLimits[ipKey] || 0;
const globalCount = staticData.rateLimits[globalKey] || 0;

if (ipCount >= PER_IP_DAILY_LIMIT) {
  return [{ json: { rateLimitExceeded: true, reason: 'ip_daily' } }];
}
if (globalCount >= GLOBAL_MONTHLY_SEARCH_LIMIT) {
  return [{ json: { rateLimitExceeded: true, reason: 'global_monthly' } }];
}

staticData.rateLimits[ipKey] = ipCount + 1;
staticData.rateLimits[globalKey] = globalCount + 1;

const body = $input.first().json.body || $input.first().json;
return [{ json: { rateLimitExceeded: false, ...body } }];

// Webhook zaten 'Respond With Job ID' ile cevap verdi; burada tekrar
// HTTP yaniti DONMUYORUZ, sadece sonucu static data'ya job_id altinda yaziyoruz.
//
// YENI: "Response Transform" JSON.parse basarisiz olduysa (parseError dolu),
// bunu ARTIK sessiz bir "completed, videos:[]" olarak degil, acik bir
// status:'error' olarak isaretliyoruz — boylece kullanici gercek nedeni gorur.
const staticData = $getWorkflowStaticData('global');
const jobId = $('Create Job').first().json.jobId;
const payload = { ...$json };

if (staticData.jobs && staticData.jobs[jobId]) {
  staticData.jobs[jobId] = { status: 'completed', createdAt: staticData.jobs[jobId].createdAt, ...payload };
}
return [{ json: payload }];

const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.jobs) staticData.jobs = {};
// 30 dakikadan eski job kayitlarini temizle (static data sismesin)
const now = Date.now();
Object.keys(staticData.jobs).forEach(id => {
  if (now - (staticData.jobs[id].createdAt || 0) > 30 * 60 * 1000) delete staticData.jobs[id];
});
const jobId = now.toString(36) + Math.random().toString(36).slice(2, 10);
staticData.jobs[jobId] = { status: 'pending', createdAt: now };
return [{ json: { ...data, jobId } }];

// DUZELTME: onceki versiyon "err.error" bir OBJE oldugunda onu dogrudan
// error alanina yaziyordu; bu da istemci tarafinda "[object Object]" olarak
// gorunuyordu. Artik hatanin gercek metnini cok katmanli/guvenli sekilde
// cikariyoruz, boylece gercek MiniMax/n8n hatasini goruruz.
const staticData = $getWorkflowStaticData('global');
const jobId = $('Create Job').first().json.jobId;
const err = $input.first().json;

function extractMessage(e) {
  if (!e) return 'Bilinmeyen hata';
  if (typeof e === 'string') return e;
  if (typeof e.message === 'string' && e.message) return e.message;
  if (typeof e.error === 'string' && e.error) return e.error;
  if (e.error && typeof e.error === 'object') {
    if (typeof e.error.message === 'string' && e.error.message) return e.error.message;
    if (typeof e.error.error === 'string' && e.error.error) return e.error.error;
    try { return JSON.stringify(e.error).slice(0, 400); } catch (_) {}
  }
  if (typeof e.description === 'string' && e.description) return e.description;
  if (typeof e.statusCode !== 'undefined') return `HTTP ${e.statusCode}: ${JSON.stringify(e).slice(0, 300)}`;
  try { return JSON.stringify(e).slice(0, 400); } catch (_) { return 'Bilinmeyen hata (JSON.stringify basarisiz)'; }
}

const errorMessage = extractMessage(err);

if (staticData.jobs && staticData.jobs[jobId]) {
  staticData.jobs[jobId] = { status: 'error', createdAt: staticData.jobs[jobId].createdAt, error: errorMessage };
}
return [{ json: { ok: false, error: errorMessage } }];

const q = $input.first().json.query || {};
const jobId = q.jobId;
const staticData = $getWorkflowStaticData('global');
const job = (staticData.jobs || {})[jobId];
if (!job) return [{ json: { status: 'not_found' } }];
return [{ json: job }];

/**
 * FORMAT RESULTS — normalize + filtre + puanlama (birleşik)
 * n8n düğümü: "Format Results" · Mode: Run Once for All Items
 * ─────────────────────────────────────────────────────────────────────────────
 * Girdi : Apify TikTok Trending (Success) ya da Mock Apify Data
 * Çıktı : TEK öğe — { status, videos[], sector, totalFound, totalViral, _ozet }
 *
 * NEDEN AYRI DÜĞÜM DEĞİL: Araya bağımsız bir puanlama düğümü koymak, alan
 * adlarını (playCount → views) değiştirdiği için "Build KOBi Filter" ve
 * frontend ile sözleşmeyi bozuyordu. Mantık buraya taşındı; dışarıya verilen
 * biçim birebir korundu, yalnızca alan EKLENDİ.
 *
 * NEDEN ACTOR'DA DEĞİL BURADA: Apify actor şemasında minLikes / dateFrom /
 * sortBy gibi parametrelerin bulunduğu varsayılamaz. Eşikleri burada tutmak,
 * actor değişse bile iş kuralını sabit bırakır.
 *
 * Kaynak: Manus araştırması (2 Eyl 2026) — filter_score.py. Python sürümündeki
 * üç alan hatası burada DÜZELTİLDİ: authorMeta.fans, videoMeta.duration ve
 * authorMeta.name noktalı anahtarla düz okunuyordu; Apify bunları iç içe nesne
 * döndürdüğü için creator "bilinmiyor", followers 0 ve duration null kalıyordu.
 * creator boş kalınca "creator başına en fazla N" kuralı tüm listeyi N kayda
 * kırpıyordu.
 */

// ─── AYARLAR — eşikleri buradan değiştirin ───────────────────────────────────
const AYAR = {
  minIzlenme:       100000,  // TR ölçeği için ayarlanmış eşik (500K çok yüksekti)
  maxYasGun:        45,      // bundan eski videolar elenir
  minPaylasimOrani: 0.0005,  // shares / views
  minSureSn:        3,
  maxSureSn:        60,
  creatorBasinaMax: 3,       // aynı hesabın listeyi doldurmasını engeller
  reklamiDahilEt:   false,
  diller:           ['tr'],  // boş dizi → dil filtresi yok
  enFazlaAday:      20,      // MiniMax'a gönderilecek aday sayısı

  // Geniş platform etiketleri: bağlam olarak kalır, pozitif sinyal sayılmaz
  gurultuEtiketleri: ['fyp', 'foryou', 'foryoupage', 'viral', 'keşfet', 'kesfet', 'explore'],

  // Puan ağırlıkları — toplamı 1.00 olmalı
  agirlik: {
    izlenme:          0.30,
    paylasim:         0.25,
    yorum:            0.15,
    momentum:         0.15,  // creator'ın takipçisine göre erişim
    formatSinyali:    0.10,
    uyarlanabilirlik: 0.05,
  },
};

// ─── Yardımcılar ─────────────────────────────────────────────────────────────

/** Noktalı yolu iç içe nesnede gezer: 'authorMeta.fans' → row.authorMeta.fans */
function yoldanOku(nesne, yol) {
  return yol.split('.').reduce((o, k) => (o == null ? undefined : o[k]), nesne);
}

/** Verilen adaylardan ilk DOLU olanı döndürür. */
function sec(row, yollar, varsayilan) {
  for (const yol of yollar) {
    const v = yoldanOku(row, yol);
    if (v !== undefined && v !== null && v !== '' &&
        !(Array.isArray(v) && v.length === 0)) return v;
  }
  return varsayilan;
}

/** '1.2k' / '3M' / '12,500' gibi değerleri de sayıya çevirir. */
function sayi(deger, varsayilan = 0) {
  if (deger === null || deger === undefined || deger === '') return varsayilan;
  if (typeof deger === 'number' && !Number.isNaN(deger)) return deger;
  let m = String(deger).trim().toLowerCase().replace(/,/g, '');
  let carpan = 1;
  if (m.endsWith('k')) { carpan = 1e3; m = m.slice(0, -1); }
  else if (m.endsWith('m')) { carpan = 1e6; m = m.slice(0, -1); }
  const n = parseFloat(m);
  return Number.isNaN(n) ? varsayilan : n * carpan;
}

/** TikTok createTime saniye cinsindedir; ISO metin de kabul edilir. */
function tarih(deger) {
  if (deger === null || deger === undefined || deger === '') return null;
  if (typeof deger === 'number') return new Date(deger * 1000);
  const n = Number(deger);
  if (!Number.isNaN(n) && String(deger).trim() !== '') return new Date(n * 1000);
  const d = new Date(deger);
  return Number.isNaN(d.getTime()) ? null : d;
}

function sure(deger) {
  if (deger === null || deger === undefined || deger === '') return null;
  if (typeof deger === 'number') return deger;
  const m = String(deger).match(/(\d+(?:\.\d+)?)/);
  return m ? parseFloat(m[1]) : null;
}

/**
 * 0–1 arası yüzdelik sıra. Tüm değerler eşitse 0.5 döner — böylece ölçülemeyen
 * bir sinyal puanı ne şişirir ne de cezalandırır.
 */
function yuzdelik(degerler) {
  const n = degerler.length;
  if (n === 0 || new Set(degerler).size <= 1) return degerler.map(() => 0.5);

  const sirali = degerler.map((v, i) => ({ v, i })).sort((a, b) => a.v - b.v);
  const sonuc = new Array(n);
  let k = 0;
  while (k < n) {
    let j = k;
    while (j + 1 < n && sirali[j + 1].v === sirali[k].v) j++;
    // Beraberlikte ortalama sıra (pandas rank method='average' karşılığı)
    const ortalamaSira = (k + j) / 2 + 1;
    for (let t = k; t <= j; t++) sonuc[sirali[t].i] = ortalamaSira / n;
    k = j + 1;
  }
  return sonuc;
}

// ─── Normalize ───────────────────────────────────────────────────────────────

function normalize(row) {
  let etiketler = sec(row, ['hashtags', 'hashtagNames'], []);
  if (typeof etiketler === 'string') {
    etiketler = (etiketler.toLowerCase().match(/#?([\wğüşöçıİĞÜŞÖÇ]+)/g) || []);
  }
  const etiketAdlari = (Array.isArray(etiketler) ? etiketler : [])
    .map((e) => (e && typeof e === 'object' ? (e.name ?? e.title) : e))
    .filter(Boolean)
    .map((e) => String(e).toLowerCase().replace(/^#/, ''));

  const creator = String(
    sec(row, ['authorMeta.name', 'authorMeta.uniqueId', 'author', 'username'], 'bilinmiyor'),
  ).toLowerCase().replace(/^@/, '');

  return {
    video_id:     String(sec(row, ['id', 'videoId', 'video_id'], '')),
    url:          String(sec(row, ['webVideoUrl', 'webVideoURL', 'videoUrl', 'url'], '')),
    creator,
    nickname:     String(sec(row, ['authorMeta.nickName', 'authorMeta.nickname', 'nickname'], creator)),
    text:         String(sec(row, ['text', 'desc', 'description'], '')),
    hashtags:     etiketAdlari,
    published_at: tarih(sec(row, ['createTime', 'create_time', 'publishedAt', 'published_at'])),
    views:        sayi(sec(row, ['playCount', 'play_count', 'views', 'viewCount'])),
    likes:        sayi(sec(row, ['diggCount', 'likeCount', 'like_count', 'likes'])),
    comments:     sayi(sec(row, ['commentCount', 'comment_count', 'comments'])),
    shares:       sayi(sec(row, ['shareCount', 'share_count', 'shares'])),
    followers:    sayi(sec(row, ['authorMeta.fans', 'authorMeta.followers', 'followerCount', 'followers'])),
    duration_s:   sure(sec(row, ['videoMeta.duration', 'duration', 'videoDuration'])),
    language:     String(sec(row, ['textLanguage', 'language', 'lang'], 'bilinmiyor')).toLowerCase(),
    music:        String(sec(row, ['musicMeta.musicName', 'musicName', 'music'], '')),
    is_ad:        Boolean(sec(row, ['isSponsored', 'is_ad', 'sponsored'], false)),
  };
}

/** İç modeli, aşağı akışın (Build KOBi Filter + frontend) beklediği biçime çevirir. */
function ciktiyaCevir(k, i) {
  return {
    // ── mevcut sözleşme, aynen korunuyor ──
    rank:           i + 1,
    title:          k.text.slice(0, 150),
    platform:       'TikTok',
    author:         k.creator,
    authorNickname: k.nickname,
    playCount:      k.views,
    diggCount:      k.likes,
    commentCount:   k.comments,
    shareCount:     k.shares,
    webVideoUrl:    k.url,
    hashtags:       k.hashtags.slice(0, 6),
    musicName:      k.music,
    // ── yeni alanlar (opsiyonel; eski tüketiciler yok sayar) ──
    trendPuani:     k.trend_puani ?? null,
    paylasimYuzde:  Math.round((k.paylasim_orani || 0) * 10000) / 100,
    yasGun:         k.yas_gun === undefined ? null : Math.round(k.yas_gun * 10) / 10,
    followers:      k.followers,
    durationSn:     k.duration_s,
  };
}

// ─── Akış ────────────────────────────────────────────────────────────────────

const ctx = $('Build Search Query').first().json;
const items = $input.all().map((i) => i.json);
const isError = items.length === 1 && items[0] && items[0].error;
const hamKayitlar = (!isError && items.length) ? items : [];

// 1) Normalize
let kayitlar = hamKayitlar.map(normalize);

// 2) Tekrarları ayıkla — aynı video farklı sorgulardan gelebilir.
//    En yüksek izlenmeli kaydı tutar.
const gorulen = new Map();
for (const k of kayitlar) {
  const anahtar = k.video_id || k.url.toLowerCase().split('?')[0].replace(/\/+$/, '');
  if (!anahtar) continue;
  const mevcut = gorulen.get(anahtar);
  if (!mevcut || k.views > mevcut.views) gorulen.set(anahtar, k);
}
kayitlar = [...gorulen.values()];

// 3) Türetilmiş ölçüler
const simdi = Date.now();
const gurultu = new Set(AYAR.gurultuEtiketleri.map((e) => e.toLowerCase().replace(/^#/, '')));

for (const k of kayitlar) {
  k.yas_gun = k.published_at
    ? Math.max(0, (simdi - k.published_at.getTime()) / 86400000)
    : 10000;
  k.paylasim_orani = k.views > 0 ? k.shares / k.views : 0;
  k.yorum_orani    = k.views > 0 ? k.comments / k.views : 0;
  k.erisim_orani   = k.followers > 0 ? k.views / k.followers : 0;
  k.gurultu_sayisi = k.hashtags.filter((h) => gurultu.has(h)).length;
}

// 4) Filtreler — izlenme eşiği ayrı tutuluyor, totalViral'ın anlamı korunsun
const izlenmeGecen = kayitlar.filter((k) => k.views >= AYAR.minIzlenme);

const gecenler = izlenmeGecen.filter((k) => {
  if (k.yas_gun > AYAR.maxYasGun) return false;
  if (k.paylasim_orani < AYAR.minPaylasimOrani) return false;
  // Süre bilinmiyorsa eleme — veri eksikliği aday kaybettirmesin
  if (k.duration_s !== null &&
      (k.duration_s < AYAR.minSureSn || k.duration_s > AYAR.maxSureSn)) return false;
  if (AYAR.diller.length > 0 &&
      !AYAR.diller.includes(k.language) && k.language !== 'bilinmiyor') return false;
  if (!AYAR.reklamiDahilEt && k.is_ad) return false;
  return true;
});

// 5) Puanlama — mutlak eşik yerine partinin kendi içindeki sıralama
if (gecenler.length > 0) {
  const izlenmePct  = yuzdelik(gecenler.map((k) => Math.log1p(k.views)));
  const paylasimPct = yuzdelik(gecenler.map((k) => k.paylasim_orani));
  const yorumPct    = yuzdelik(gecenler.map((k) => k.yorum_orani));
  const momentumPct = yuzdelik(gecenler.map((k) => Math.log1p(k.erisim_orani)));

  gecenler.forEach((k, i) => {
    // Özgün etiket çeşitliliği = formatın tanımlanabilirliği
    const ozgunEtiket      = k.hashtags.filter((h) => !gurultu.has(h)).length;
    const formatSinyali    = Math.min(ozgunEtiket / 5, 1);
    const uyarlanabilirlik = 1 - Math.min(k.gurultu_sayisi, 5) / 5;
    const tazelik          = Math.exp(-k.yas_gun / Math.max(AYAR.maxYasGun, 1));

    const a = AYAR.agirlik;
    k.trend_puani = Math.round(100 * (
      a.izlenme * izlenmePct[i] +
      a.paylasim * paylasimPct[i] +
      a.yorum * yorumPct[i] +
      a.momentum * momentumPct[i] +
      a.formatSinyali * formatSinyali +
      a.uyarlanabilirlik * uyarlanabilirlik
    ) * tazelik * 10) / 10;
  });

  // 6) Sırala ve creator başına sınırla
  gecenler.sort((x, y) => y.trend_puani - x.trend_puani || y.views - x.views);
}

let secilenler = [];
const creatorSayaci = new Map();
for (const k of gecenler) {
  const n = (creatorSayaci.get(k.creator) ?? 0) + 1;
  creatorSayaci.set(k.creator, n);
  if (n <= AYAR.creatorBasinaMax) secilenler.push(k);
  if (secilenler.length >= AYAR.enFazlaAday) break;
}

/*
 * YEDEK MOD — eşikler bu partiyi tamamen elediyse.
 *
 * Apify çalıştırma başına yalnızca ~10 kayıt döndüğü için tazelik + paylaşım
 * oranı + süre filtrelerinin üst üste binmesi listeyi sıfırlayabiliyor.
 * O durumda araç boş dönmesin diye eski davranışa (izlenme eşiği + izlenmeye
 * göre sıralama) düşüyoruz. _ozet.mod alanı hangi yolun kullanıldığını söyler.
 */
let mod = 'puanlama';
if (secilenler.length === 0 && izlenmeGecen.length > 0) {
  mod = 'yedek';
  secilenler = [...izlenmeGecen]
    .sort((a, b) => b.views - a.views)
    .slice(0, AYAR.enFazlaAday);
}

const videos = secilenler.map(ciktiyaCevir);

return [{
  json: {
    status:     'completed',
    videos,
    sector:     ctx.sector || '',
    totalFound: hamKayitlar.length,
    totalViral: izlenmeGecen.length,
    _ozet: {
      mod,                              // 'puanlama' | 'yedek'
      // false → sektör haritada bulunamadı, #keşfet'e düşüldü (sessiz kalmasın)
      hashtagEslesti: ctx.hashtagEslesti !== false,
      ham:          hamKayitlar.length, // Apify'dan gelen
      tekil:        kayitlar.length,    // tekrarlar ayıklandıktan sonra
      izlenmeGecen: izlenmeGecen.length,
      filtreGecen:  gecenler.length,
      kabul:        videos.length,
      esikler:      AYAR,
    },
  },
}];

/**
 * APPLY KOBi FILTER — MiniMax cevabını videolara işler
 * n8n düğümü: "Apply KOBi Filter"
 * ─────────────────────────────────────────────────────────────────────────────
 * MiniMax artık zengin JSON döndürüyor (bkz. Build KOBi Filter):
 *   [{"n":1,"format":"POV","uyum":85,"zorluk":2,"guvenlik":5}]
 *
 * ÜÇ KADEMELİ ÇÖZÜMLEME — model bazen istenen biçimden sapıyor:
 *   1. JSON dizisi        → tam veri, arayüzdeki rozetler dolar
 *   2. "1,3,5" numaraları → eski davranış, yalnızca eleme
 *   3. hiçbiri            → ilk 12 video, elenmemiş
 * Her kademede hangi yolun kullanıldığı _cozumleme alanına yazılıyor; sürekli
 * 'yedek' görünüyorsa promptun bozulduğu anlaşılır.
 */

const ctx = $('Build KOBi Filter').first().json;
const allVideos = ctx.videos || [];

/** Model bazen ```json ... ``` sarmalıyor ya da önüne metin koyuyor. */
function jsonDiziAyikla(metin) {
  const bas = metin.indexOf('[');
  const son = metin.lastIndexOf(']');
  if (bas === -1 || son === -1 || son < bas) return null;
  try {
    const cozulen = JSON.parse(metin.slice(bas, son + 1));
    return Array.isArray(cozulen) ? cozulen : null;
  } catch {
    return null;
  }
}

/** 1–5 aralığına, 0–100 aralığına vb. güvenli kırpma. */
function araliktaSayi(deger, alt, ust) {
  const n = Number(deger);
  if (!Number.isFinite(n)) return undefined;
  return Math.min(Math.max(Math.round(n), alt), ust);
}

const icerik = ($input.first().json?.choices?.[0]?.message?.content || '').trim();

let secilen = [];
let cozumleme = 'yedek';

// ── 1. kademe: zengin JSON ──────────────────────────────────────────────────
const dizi = jsonDiziAyikla(icerik);
if (dizi && dizi.length > 0) {
  secilen = dizi
    .map((k) => {
      const i = Number(k?.n) - 1;
      if (!Number.isInteger(i) || i < 0 || i >= allVideos.length) return null;
      return {
        ...allVideos[i],
        formatAdi:         typeof k.format === 'string' ? k.format.slice(0, 60) : undefined,
        adaptabilityScore: araliktaSayi(k.uyum, 0, 100),
        uretimZorlugu:     araliktaSayi(k.zorluk, 1, 5),
        markaGuvenligi:    araliktaSayi(k.guvenlik, 1, 5),
        // trendDurumu KASITLI olarak doldurulmuyor — bkz. Build KOBi Filter
      };
    })
    .filter(Boolean);
  if (secilen.length > 0) cozumleme = 'json';
}

// ── 2. kademe: eski "1,3,5" biçimi ──────────────────────────────────────────
if (secilen.length === 0 && icerik) {
  const indeksler = icerik.split(',')
    .map((s) => parseInt(s.trim(), 10) - 1)
    .filter((i) => Number.isInteger(i) && i >= 0 && i < allVideos.length);
  if (indeksler.length > 0) {
    secilen = indeksler.map((i) => allVideos[i]);
    cozumleme = 'numara';
  }
}

// ── 3. kademe: elenmemiş ────────────────────────────────────────────────────
if (secilen.length === 0) {
  secilen = allVideos.slice(0, 12);
  cozumleme = 'yedek';
}

// Uyum puanı varsa ona göre sırala; yoksa gelen sıra (trend puanı) korunur.
if (cozumleme === 'json') {
  secilen.sort((a, b) => (b.adaptabilityScore ?? 0) - (a.adaptabilityScore ?? 0));
}

const videos = secilen.slice(0, 12).map((v, i) => ({ ...v, rank: i + 1 }));

return [{
  json: {
    status:        'completed',
    videos,
    sector:        ctx.sector || '',
    totalFound:    ctx.totalFound,
    totalViral:    ctx.totalViral,
    filteredCount: videos.length,
    _ozet:         { ...(ctx._ozet || {}), cozumleme },
  },
}];

